mapper:
// 매치 상세 조회
SELECT * FROM matches WHERE id = #{matchId} AND status != 'DELETED'
// 목록 조회
SELECT * FROM matches WHERE status != 'DELETED' ORDER BY match_date DESC LIMIT #{size} OFFSET #{offset}
// 매치 생성
INSERT INTO matches ( title, sport_type, match_date, location_name, latitude, longitude, address, max_players, current_players, skill_level, entry_fee, description, status ) VALUES ( #{title}, #{sportType}, #{matchDate}, #{locationName}, #{latitude}, #{longitude}, #{address}, #{maxPlayers}, #{currentPlayers}, #{skillLevel}, #{entryFee}, #{description}, #{status} )
// 매치 수정(업데이트)
UPDATE matches
title = #{title}, match_date = #{matchDate}, max_players = #{maxPlayers}, entry_fee = #{entryFee}, description = #{description},
WHERE id = #{matchId} AND status != 'DELETED'
// 랜덤 매칭
SELECT * FROM ( SELECT id AS matchId, title, sport_type AS sportType, match_date AS matchDate, location_name AS locationName, entry_fee AS entryFee,
-- 🔥 거리 계산 (km) (6371 * ACOS( COS(RADIANS(#{latitude})) * COS(RADIANS(latitude)) * COS(RADIANS(longitude) - RADIANS(#{longitude})) + SIN(RADIANS(#{latitude})) * SIN(RADIANS(latitude)) )) AS distance
FROM matches WHERE status = 'OPEN' AND current_players < max_players
AND sport_type = #{sportType}
AND DATE(match_date) = #{date}
AND entry_fee <= #{maxFee}
AND skill_level = #{skillLevel}
) t
WHERE t.distance <= #{radius}
ORDER BY RAND() LIMIT 1
UPDATE matches SET status = 'DELETED', updated_at = NOW() WHERE id = #{matchId} AND status != 'DELETED'
